// MQTT güvenlik sistemi: kapı sensörü ve PIR alarm mesajı yayınlar.
// "ev/guvenlik/komut" konusuna "kur" gelince alarm kurulur, "coz" gelince çözülür.
#include <WiFi.h>
#include <PubSubClient.h>

const char* AG_ADI = "EvimWiFi";               // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";              // kendi Wi-Fi parolan
const char* MQTT_SUNUCU = "broker.hivemq.com"; // ücretsiz genel sunucu; kendi sunucunu da yazabilirsin
const int MQTT_PORT = 1883;
const char* MQTT_KIMLIK = "kendinyap-guvenlik";

const char* KONU_KOMUT = "ev/guvenlik/komut";  // dinlenir: kur / coz
const char* KONU_DURUM = "ev/guvenlik/durum";  // yayınlanır: kurulu / cozuldu
const char* KONU_ALARM = "ev/guvenlik/alarm";  // yayınlanır: kapi / hareket
const char* KONU_KAPI = "ev/guvenlik/kapi";    // yayınlanır: acik / kapali

const int KAPI_PIN = 19;    // kapı sensörü (öbür ucu GND)
const int PIR_PIN = 27;     // PIR OUT
const int BUZZER_PIN = 25;  // buzzer +
const int LED_PIN = 4;      // durum LED'i

const unsigned long PIR_ISINMA_MS = 30000;   // PIR açılışta 30 sn ısınır; bu sürede hareket sayılmaz
const unsigned long ALARM_SURE_MS = 20000;   // alarm en çok 20 sn öter
const unsigned long KAPI_TITRESIM_MS = 50;   // kapı sensörü titreşimini yok say

WiFiClient wifiIstemci;
PubSubClient mqtt(wifiIstemci);

bool kurulu = false;
bool alarmCaliyor = false;
unsigned long alarmBaslangic = 0;
unsigned long sonBip = 0;
bool bipYuksek = false;
int sonKapi = LOW;
unsigned long kapiDegisti = 0;
int sonPir = LOW;

void durumYayinla() {
  mqtt.publish(KONU_DURUM, kurulu ? "kurulu" : "cozuldu", true);  // kalıcı mesaj: yeni bağlanan da görür
  Serial.println(kurulu ? "Alarm kuruldu." : "Alarm cozuldu.");
}

void alarmBaslat(const char* neden) {
  mqtt.publish(KONU_ALARM, neden);
  Serial.printf("ALARM: %s\n", neden);
  if (!alarmCaliyor) {
    alarmCaliyor = true;
    alarmBaslangic = millis();
  }
}

void alarmDurdur() {
  alarmCaliyor = false;
  noTone(BUZZER_PIN);
}

// Abone olunan konuya mesaj gelince çağrılır.
void mesajGeldi(char* konu, byte* veri, unsigned int uzunluk) {
  String mesaj;
  for (unsigned int i = 0; i < uzunluk; i++) mesaj += (char)veri[i];
  mesaj.trim();
  mesaj.toLowerCase();
  Serial.printf("Mesaj: %s = %s\n", konu, mesaj.c_str());
  if (String(konu) != KONU_KOMUT) return;
  if (mesaj == "kur") {
    kurulu = true;
    durumYayinla();
  } else if (mesaj == "coz") {
    kurulu = false;
    alarmDurdur();
    durumYayinla();
  }
}

void mqttBaglan() {
  while (!mqtt.connected()) {
    Serial.print("MQTT'ye baglaniyor... ");
    if (mqtt.connect(MQTT_KIMLIK)) {
      Serial.println("tamam");
      mqtt.subscribe(KONU_KOMUT);
      durumYayinla();
    } else {
      Serial.println("olmadi, 2 sn sonra tekrar");
      delay(2000);
    }
  }
}

void kapiDenetle() {
  int kapi = digitalRead(KAPI_PIN);  // HIGH: mıknatıs uzak, kapı açık
  if (kapi == sonKapi) {
    kapiDegisti = millis();
    return;
  }
  if (millis() - kapiDegisti < KAPI_TITRESIM_MS) return;
  sonKapi = kapi;
  mqtt.publish(KONU_KAPI, kapi == HIGH ? "acik" : "kapali");
  Serial.println(kapi == HIGH ? "Kapi acildi" : "Kapi kapandi");
  if (kapi == HIGH && kurulu) alarmBaslat("kapi");
}

void pirDenetle() {
  int pir = digitalRead(PIR_PIN);
  if (pir == HIGH && sonPir == LOW && millis() > PIR_ISINMA_MS && kurulu) alarmBaslat("hareket");
  sonPir = pir;
}

// Alarm çalarken buzzer iki tonla öter, LED hızlı yanıp söner.
// Kuruluyken LED sürekli yanar, çözülünce söner.
void yerelAlarm() {
  if (alarmCaliyor && millis() - alarmBaslangic > ALARM_SURE_MS) alarmDurdur();
  if (alarmCaliyor) {
    if (millis() - sonBip >= 250) {
      sonBip = millis();
      bipYuksek = !bipYuksek;
      tone(BUZZER_PIN, bipYuksek ? 2200 : 1400, 240);
      digitalWrite(LED_PIN, bipYuksek ? HIGH : LOW);
    }
  } else {
    digitalWrite(LED_PIN, kurulu ? HIGH : LOW);
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(KAPI_PIN, INPUT_PULLUP);
  pinMode(PIR_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  sonKapi = digitalRead(KAPI_PIN);

  WiFi.begin(AG_ADI, PAROLA);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Wi-Fi tamam, IP: ");
  Serial.println(WiFi.localIP());
  mqtt.setServer(MQTT_SUNUCU, MQTT_PORT);
  mqtt.setCallback(mesajGeldi);
  Serial.println("PIR 30 sn isiniyor; kapi sensoru hemen calisir.");
}

void loop() {
  if (!mqtt.connected()) mqttBaglan();
  mqtt.loop();
  kapiDenetle();
  pirDenetle();
  yerelAlarm();
  delay(10);
}
